"""Compare verified GPU completion captures with retained original NPU evidence."""
from pathlib import Path
import sys,json,numpy as np
ROOT=Path(__file__).resolve().parent;REPO=ROOT.parents[3]
sys.path.insert(0,str(REPO/'skills/precision-compare/scripts'))
from array_compare import compare_arrays
from score_metrics import reduce_scores
OLD=REPO/'projects/precision-repair/cases/autonomous-cross-platform-20261025T035100Z/evidence/npu/runs'
NPU={'short-bf16':'npu-inference-20261025T034918Z','short-fp32':'npu-reference-20261025T035253Z','long-bf16':'npu-long-inference-20261025T035506Z','long-fp32':'npu-long-reference-20261025T035601Z'}
def load_npz(p):
 with np.load(p,allow_pickle=False) as f:return {k:f[k] for k in f.files}
def read(p):return json.loads(p.read_text())
result={'inference':{},'sft':{},'classification':'No library defect established by these comparisons'}
for label,folder in NPU.items():
 g=(ROOT/'evidence'/label) if label.endswith('bf16') else (ROOT/'completion-evidence/inference-fp32'/label)
 n=OLD/folder;gi=read(g/'inputs.json');ni=read(n/'inputs.json')
 for key in ['input_ids','rows','position_ids','mask','model_revision']:
  assert gi[key]==ni[key],(label,key)
 a=load_npz(g/'baseline.npz');b=load_npz(n/'baseline.npz');report=compare_arrays(a,b,expected=['logits'],metrics=True)
 ga=a['logits'];na=b['logits'];assert ga.shape==na.shape
 report['positions']=int(np.prod(ga.shape[:-1]));report['top1_disagreements']=int(np.count_nonzero(ga.argmax(-1)!=na.argmax(-1)));report['side_paths']={'gpu':str(g),'npu':str(n)}
 report['input_dtype_note']='Native dtype is taken from scope identity and native launch source; embedded input template dtype strings are not authoritative.'
 result['inference'][label]=report
G=ROOT/'completion-evidence/small-sft-export/accelerated';N=REPO/'projects/precision-repair/cases/autonomous-cross-sft-20261025T034857Z/npu-accelerated-evidence/export-accelerated/accelerated'
gc=read(ROOT/'completion-evidence/sft/configuration.json');nc=read(N.parents[1]/'accelerated-artifacts/configuration.json')
for key in ['ids','labels','mask','positions','lora','trainable','parameters','language_layers','base_dtype']:assert gc[key]==nc[key],('sft',key)
for stage in ['initial','gradients','updates']:
 a=load_npz(G/(stage+'.npz'));b=load_npz(N/(stage+'.npz'));expected=list(gc['trainable']);assert set(a)==set(b)==set(expected)
 result['sft'][stage]=compare_arrays(a,b,expected=expected,metrics=True)
assert result['sft']['initial']['exact_equal'],'Cross-device initial adapter state must match exactly'
gt=read(G/'targets.json');nt=read(N/'targets.json')
def scores(rows):return {(r['position'],r['token']):r['logprob'] for r in rows}
result['sft']['targets']=reduce_scores(scores(gt[0]),scores(nt[0]))
result['sft']['native_results']={'gpu':read(ROOT/'completion-evidence/sft/result.json'),'npu':read(N.parents[1]/'accelerated-artifacts/result.json')}
result['sft']['oracle']={'gpu':read(ROOT/'completion-evidence/sft/attention-fp64.json'),'npu':read(N.parents[1]/'accelerated-artifacts/attention-fp64.json')}
(ROOT/'cross-comparison.json').write_text(json.dumps(result,indent=2,allow_nan=False)+'\n')
print(json.dumps({'inference':{k:{'max_abs':v['metrics']['max_abs']['value'],'positions':v['positions'],'top1_disagreements':v['top1_disagreements']} for k,v in result['inference'].items()},'sft':{'initial_equal':result['sft']['initial']['exact_equal'],'targets':result['sft']['targets'],'gradients':result['sft']['gradients']['metrics'],'updates':result['sft']['updates']['metrics']}},indent=2))

