from pathlib import Path
import json,sys,numpy as np
root=Path(sys.argv[1]);repo=root.parents[3];sys.path.insert(0,str(repo/'skills/precision-compare/scripts'))
from array_compare import compare_arrays
npu=repo/'projects/precision-repair/cases/autonomous-cross-sft-20261025T034857Z/npu-accelerated-evidence/export-accelerated/accelerated';gpu=root/'completion-evidence/small-sft-export/accelerated'
report={};lr=1e-4;eps=1e-8
for side,path in [('gpu',gpu),('npu',npu)]:
 with np.load(path/'initial.npz') as f:initial={k:f[k] for k in f.files}
 with np.load(path/'gradients.npz') as f:grad={k:f[k] for k in f.files}
 with np.load(path/'updates.npz') as f:actual={k:f[k] for k in f.files}
 expected={}
 for k,before in initial.items():
  g=grad[k].astype(np.float64);after=(before.astype(np.float64)-lr*g/(np.abs(g)+eps)).astype(np.float32)
  expected[k]=(after.astype(np.float64)-before.astype(np.float64)).astype(np.float32)
 report[side]=compare_arrays(actual,expected,expected=list(initial),metrics=True)
 key='base_model.model.model.language_model.layers.7.self_attn.v_proj.lora_B.default.weight';coordinate=(302,1)
 report[side]['cross_max_update_coordinate']={'parameter':key,'index':list(coordinate),'gradient':float(grad[key][coordinate]),'stored_update':float(actual[key][coordinate]),'formula_update':float(expected[key][coordinate])}
(root/'adamw-first-step-check.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({s:{'max_formula_error':r['metrics']['max_abs']['value'],'max_update_coordinate':r['cross_max_update_coordinate']} for s,r in report.items()},indent=2))
